import {buyCosmetic,selectCosmetic,activeFrame,normalizeNickname} from '../systems/profile.js';
import {profileScreen,cosmeticPreview} from './profile.js';
import {Motion} from './motion.js';
import {SceneAnimator} from './scene.js';
import {offers,starterCard,rewardedCard} from './offers.js';
import {MonetizationController,starterEligible} from '../systems/monetization.js';
import {CONFIG,HOUSING,SKILLS,JOBS,ITEMS,xpNeeded} from '../data/config.js';
import {EVENTS} from '../data/events.js';
import * as game from '../core/game.js';import {SaveManager} from '../core/save.js';
import {nextEvent,resolveEvent} from '../systems/events.js';
import {LeaderboardService,SoundManager,AnalyticsService,AdsService,PurchaseService} from '../services/platform.js';
import {t,setLanguage,getLanguage,money,number} from '../locales/index.js';
import {icon} from './icons.js';import * as views from './screens.js';
const root=document.getElementById('app'),dialog=document.getElementById('modal'),toastEl=document.getElementById('toast');
let storage;try{storage=localStorage;}catch{storage={getItem(){throw Error('Storage disabled')},setItem(){throw Error('Storage disabled')}};}
const saves=new SaveManager(storage),leaderboard=new LeaderboardService(),sound=new SoundManager(),analytics=new AnalyticsService();
let profileView='frames',cosmeticKind='frame',cosmeticId='standard';
let sourceRect=null,pendingProvider=null,services,storeController,previewItemId=null,lastLanguage=null,lastSceneKey=null;
let s,tab='life',workView='career',shopView='items',branch='all',shopFilter='all',rankMode='wealth',modal=null,frozen=false,timer,toastTimer,saveTimer,pendingImport=null;
const dev=['localhost','127.0.0.1','terminal.local'].includes(location.hostname)&&new URLSearchParams(location.search).has('dev');
const motion=new Motion(()=>s?.settings),sceneAnimator=new SceneAnimator(()=>s?.settings);
function start(){s=saves.load();try{if(!storage.getItem('generation-z.save.v2'))s.settings.language=navigator.language.startsWith('uk')?'uk':navigator.language.startsWith('en')?'en':'ru';}catch{}setLanguage(s.settings.language);document.documentElement.lang=s.settings.language;services={ads:new AdsService(),purchases:new PurchaseService()};wireStore();analytics.track('game_start');render();if(s.offline)showModal('offline');if(saves.warning)toast(t('ui.'+({recovered:'recovered',corrupt:'corrupt',storage:'storageError'}[saves.warning]||'storageError')),7000);persist();timer=setInterval(tick,1000);saveTimer=setInterval(persist,CONFIG.autosaveMs);if(dev){import('./debug.js').then(m=>m.attach({get:()=>s,replace:v=>{s=v;render();persist();},refresh:()=>{render();persist();},motion,sceneAnimator}));if(new URLSearchParams(location.search).has('commerce'))import('../services/test-commerce.js').then(m=>{services=m.testProviders(showTestProvider);wireStore();render();});}}
function freeze(){frozen=true;clearInterval(timer);clearInterval(saveTimer);dialog.close();root.innerHTML=`<div class="empty tab-warning">${icon('lock')}<h1>${t('ui.title')}</h1><p>${t('ui.otherTab')}</p><button class="button primary" onclick="location.reload()">${t('ui.refresh')}</button></div>`;}
if(navigator.locks){navigator.locks.request('generation-z-writer',{ifAvailable:true},async lock=>{if(!lock){setLanguage('ru');freeze();return;}start();await new Promise(resolve=>{window.addEventListener('pagehide',resolve,{once:true});});}).catch(()=>{if(!s)start();});}else{start();window.addEventListener('storage',e=>{if(e.key==='generation-z.save.v2')freeze();});}
function persist(){if(!s||frozen)return;if(!saves.save(s)){const warning=document.getElementById('save-warning');if(warning){warning.hidden=false;warning.textContent=t('ui.storageError');}}}
function toast(message,ms=2600){toastEl.textContent=message;toastEl.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('visible'),ms);}
function wireStore(){storeController=new MonetizationController({ads:services.ads,purchases:services.purchases,getState:()=>s,persist});}
function feedback(type){if(s.settings.sound)sound.tone(type);if(s.settings.music&&!sound.musicTimer)sound.music(true);if(s.settings.vibration&&navigator.vibrate)navigator.vibrate(type==='level'?[18,20,28]:type==='achievement'?[12,15,12]:type==='unlock'?18:8);}
function render(){if(frozen)return;const focus=document.activeElement?.dataset,oldWallet=document.querySelector('.wallet'),oldScene=document.querySelector('.scene-art'),sceneKey=JSON.stringify([s.housing,s.equipped,s.commerce.decorations]);root.innerHTML=`${views.header(s)}<p id="save-warning" class="save-warning" ${saves.available?'hidden':''}>${t('ui.storageError')}</p><main id="screen">${tab==='life'?views.life(s):tab==='work'?views.workScreen(s,workView,branch):tab==='shop'?views.shopScreen(s,shopView,shopFilter):views.rankingScreen(s,leaderboard,rankMode)}</main><nav class="bottom-nav" aria-label="${t('ui.title')}">${['life','work','shop','rating'].map(n=>`<button data-action="nav" data-id="${n}" class="nav-item ${tab===n?'active':''}" ${tab===n?'aria-current="page"':''}>${icon(n)}<span>${t('ui.'+n)}</span></button>`).join('')}</nav>`;if(oldWallet&&lastLanguage===s.settings.language)document.querySelector('.wallet').replaceWith(oldWallet);if(oldScene&&lastSceneKey===sceneKey&&document.querySelector('.scene-art'))document.querySelector('.scene-art').replaceWith(oldScene);lastLanguage=s.settings.language;lastSceneKey=sceneKey;if(tab==='shop'&&shopView==='items'){const content=starterCard(s,services);if(content)document.querySelector('.segmented')?.insertAdjacentHTML('afterend',content);}sceneAnimator.bind();sceneAnimator.applySettings();const avatar=document.querySelector('.avatar');if(avatar)avatar.className=`avatar profile-avatar frame-${activeFrame(s)}`;updateNumbers();if(modal)renderModal();if(focus?.action){const match=[...document.querySelectorAll('[data-action]')].find(b=>b.dataset.action===focus.action&&b.dataset.id===focus.id);match?.focus({preventScroll:true});}}
function updateNumbers(){const set=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value;};motion.counter(document.getElementById('bank-value'),'bank',s.bank,money);motion.counter(document.getElementById('money-value'),'money',s.money,money);motion.counter(document.getElementById('income-value'),'income',game.income(s),money);motion.counter(document.getElementById('gems-value'),'gems',s.gems,n=>number(Math.round(n)));set('boost-time',s.boosts.length?`${game.boostFactor(s)}× · ${Math.max(0,Math.ceil((Math.max(...s.boosts.filter(b=>b.factor===game.boostFactor(s)).map(b=>b.endsAt))-s.lastTick)/60000))} ${t('ui.min')}`:'');set('level-value',s.level);set('xp-label',s.level===CONFIG.maxLevel?t('ui.max'):`${number(s.xp)} / ${number(xpNeeded(s.level))} XP`);const fill=document.getElementById('xp-fill');if(fill)fill.style.width=`${s.level===CONFIG.maxLevel?100:s.xp/(xpNeeded(s.level))*100}%`;const collect=document.querySelector('[data-action="collect"]');if(collect)collect.disabled=s.bank<1;const work=document.querySelector('[data-action="work"]');if(work){const left=Math.max(0,Math.ceil((s.lastWork+CONFIG.workCooldownMs-Date.now())/1000));work.disabled=left>0;work.innerHTML=left?`${icon('clock')}${left} ${t('ui.sec')}`:`+${money(game.income(s)*CONFIG.workSeconds)}<small>+${CONFIG.workXP} XP</small>`;}if(s.training)set('training-time',`${Math.max(0,Math.ceil((s.training.endsAt-Date.now())/1000))} ${t('ui.sec')}`);document.querySelectorAll('[data-price]').forEach(b=>{b.disabled=s.money<Number(b.dataset.price);});}
function tick(){if(frozen||document.hidden)return;const oldTraining=s.training,level=s.level,oldBoost=s.boosts.length,oldOffer=starterEligible(s);game.advance(s,Date.now());const event=nextEvent(s);if(oldTraining&&!s.training){feedback('purchase');toast(t('ui.courseDone'));persist();render();}else if(event||oldBoost!==s.boosts.length||oldOffer!==starterEligible(s)){persist();render();}else {updateNumbers();if(tab==='life'&&!s.tutorial){const bar=document.querySelector('.goal-card .progress');if(bar){bar.setAttribute('aria-valuenow',Math.min(25,s.bank));bar.firstElementChild.style.width=Math.min(100,s.bank/25*100)+'%';}}}if(s.level>level){feedback('level');render();motion.celebrate(`${t('ui.levelUp')} ${s.level}`,`+${(s.level-level)*CONFIG.levelGems} ${t('ui.gems')}`);motion.shake();}}
function showModal(name){if(pendingProvider&&name!=='testProvider'){pendingProvider('cancel');pendingProvider=null;}modal=name;renderModal();if(!dialog.open)dialog.showModal();}
function renderModal(){let title=t('ui.'+modal),body='';if(modal==='profile'){body=profileScreen(s,profileView);}else if(modal==='cosmeticPreview'){title=t('ui.preview');body=cosmeticPreview(s,cosmeticKind,cosmeticId);}else if(modal==='bonuses'){body=offers(s,{...services,busy:storeController.busy});}else if(modal==='testProvider'){title=t('ui.testMode');body=`<div class="test-provider"><p>${t('ui.testDescription')}</p>${views.button(t('ui.testSuccess'),'providerResult','success','button secondary')}${views.button(t('ui.testCancel'),'providerResult','cancel','button secondary')}${views.button(t('ui.testFailure'),'providerResult','failure','button danger')}</div>`;}else if(modal==='previewItem'){const item=ITEMS.find(i=>i.id===previewItemId);title=t('ui.preview');body=item?`<div class="offline-content"><span class="offline-icon">${icon(item.slot)}</span><h3>${t(item.name)}</h3><p>+${Math.round(item.bonus*100)}% ${t('ui.incomeBonus')}</p><strong>${money(item.price)}</strong><p>${t('ui.level')} ${item.levelRequirement}</p></div>`:'';}if(modal==='tasks')body=views.tasks(s);else if(modal==='achievements')body=views.achievements(s);else if(modal==='settings')body=views.settings(s);else if(modal==='offline'){const o=s.offline;title=t('ui.offline');body=`<div class="offline-content"><span class="offline-icon">${icon('sun')}</span><p>${t('ui.absent')}: ${o?`${Math.floor(o.seconds/3600)} ${t('ui.hour')} ${Math.floor(o.seconds%3600/60)} ${t('ui.min')}`:''}</p><strong>${money(o?.money||0)}</strong><p>${t('ui.offlineInfo')}</p>${views.button(t('ui.collect'),'offlineClaim','','button primary')}${rewardedCard(s,'offline',services)}</div>`;}else if(modal==='event'){const e=EVENTS[s.event];if(!e){closeModal();return;}const idx={ru:0,uk:1,en:2}[getLanguage()];body=`<div class="event-content"><span class="offline-icon">${icon('spark')}</span><h3>${e.text[idx]}</h3>${views.button(`${t('ui.takeChance')}<small>−${money(Math.round(game.income(s)*e.costSeconds))} · +1 ${t('skill.'+e.skill)} · +${e.rewardXP} XP</small>`,'eventChoice','try','button primary',s.money<Math.round(game.income(s)*e.costSeconds))}${views.button(`${t('ui.playSafe')}<small>+${e.safeXP} XP</small>`,'eventChoice','safe','button secondary')}</div>`;}else if(modal==='resetConfirm'||modal==='importConfirm'){title=t(modal==='resetConfirm'?'ui.reset':'ui.import');body=`<p>${t(modal==='resetConfirm'?'ui.resetAsk':'ui.importAsk')}</p><div class="confirm-actions">${views.button(t('ui.cancel'),'settings','','button secondary')}${views.button(t('ui.confirm'),modal==='resetConfirm'?'resetConfirmed':'importConfirmed','','button danger')}</div>`;}
dialog.classList.toggle('profile-modal',['profile','cosmeticPreview'].includes(modal));
dialog.innerHTML=`<div class="modal-heading"><h2>${title}</h2>${views.button(icon('close'),'close','','icon-button',false,`aria-label="${t('ui.close')}"`)}</div><div class="modal-body">${body}</div>`;}
function closeModal(){if(pendingProvider){pendingProvider('cancel');pendingProvider=null;}modal=null;dialog.close();}
dialog.addEventListener('close',()=>{if(pendingProvider){pendingProvider('cancel');pendingProvider=null;}modal=null;});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function completeVisual(previous,kind,result,message,oldRoom){
 const leveled=s.level>previous;render();
 feedback(leveled?'level':kind);if(result.amount)motion.coins(sourceRect);motion.xp();sceneAnimator.react();
 if(leveled){motion.celebrate(`${t('ui.levelUp')} ${s.level}`,`+${(s.level-previous)*CONFIG.levelGems} ${t('ui.gems')}`,'spark');motion.shake();analytics.track('level_up',{level:s.level});}
 else if(kind==='unlock')motion.celebrate(t('ui.unlockSequence'),message||'','work');
 else if(kind==='achievement')motion.celebrate(t('ui.achievementSequence'),message||t('ui.reward'),'rating');
 else if(kind==='purchase'&&!oldRoom){motion.celebrate(t('ui.itemReceived'),message||t('ui.purchased'),'shop');}
 else if(message)toast(message);else if(result.amount)toast(`+${money(result.amount)}`);
 if(oldRoom){motion.room(oldRoom);motion.celebrate(t('ui.roomUpgrade'),t(HOUSING[s.housing].name),'life');motion.shake();}
}
function transact(fn,kind,message,housing=false){const previous=s.level,oldHome=s.housing;let oldRoom=document.querySelector('.room');if(housing&&!oldRoom){const holder=document.createElement('div');holder.innerHTML=views.life(s);oldRoom=holder.querySelector('.room');}game.advance(s,Date.now());const result=fn();if(!result.ok){toast(t('error.'+result.reason));updateNumbers();return result;}if(oldHome!==s.housing)tab='life';persist();completeVisual(previous,kind,result,message,oldHome!==s.housing?oldRoom:null);if(oldHome!==s.housing)window.scrollTo({top:0,behavior:'instant'});return result;}
function showTestProvider(){showModal('testProvider');return new Promise(resolve=>{pendingProvider=resolve;});}
async function commerceAction(action,id){const previous=s.level;const result=action==='starter'?await storeController.starter():await storeController.rewarded(id);if(result.ok){closeModal();completeVisual(previous,action==='starter'?'purchase':'achievement',result,t('ui.reward'));}else{toast(t('error.'+result.reason));if(modal!=='testProvider'&&modal)renderModal();}}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target||target.disabled||frozen||!s)return;sourceRect=target.getBoundingClientRect();const {action,id}=target.dataset;if(!['work','collect','offlineClaim','job','item','housing','train','quest','achievement','gift','eventChoice','nav'].includes(action))feedback('click');if(action==='providerResult'){const resolve=pendingProvider;pendingProvider=null;closeModal();resolve?.(id);return;}if(action==='rewarded'||action==='starter'){commerceAction(action,id);return;}if(action==='previewItem'){previewItemId=id;showModal('previewItem');return;}
if(action==='profile'){showModal('profile');motion.animate(dialog.querySelector('.profile-hero'),[{opacity:.3,transform:'scale(.97)'},{opacity:1,transform:'scale(1)'}],{duration:180});return;}
if(action==='profileTab'){profileView=id==='titles'?'titles':'frames';renderModal();return;}
if(action==='profilePreview'){[cosmeticKind,cosmeticId]=id.split(':');showModal('cosmeticPreview');motion.animate(dialog.querySelector('.profile-hero'),[{opacity:.3,transform:'scale(.97)'},{opacity:1,transform:'scale(1)'}],{duration:180});return;}
if(action==='profileBuy'||action==='profileSelect'){const [kind,key]=id.split(':');const result=action==='profileBuy'?buyCosmetic(s,kind,key):selectCosmetic(s,kind,key);if(result.ok){persist();render();if(action==='profileBuy')feedback('purchase');motion.animate(dialog.querySelector('.profile-avatar'),[{transform:'scale(.92)'},{transform:'scale(1.06)'},{transform:'scale(1)'}],{duration:230});}const status=dialog.querySelector('#profile-feedback');if(status)status.textContent=t(result.ok?'profile.saved':'error.'+result.reason);return;}
if(action==='profileName'){s.profile.nickname=normalizeNickname(document.getElementById('profile-name')?.value);persist();renderModal();dialog.querySelector('#profile-feedback').textContent=t('profile.saved');return;}
if(action==='nav'){tab=id;render();motion.enter();window.scrollTo({top:0,behavior:'instant'});feedback('click');return;}
if(action==='goal'){if(id==='skills'){tab='work';workView='skills';}else if(id==='housing'){tab='shop';shopView='housing';}else tab=id;render();motion.enter();window.scrollTo({top:0,behavior:'instant'});return;}
if(['workView','shopView','branch','shopFilter','rankMode'].includes(action)){if(action==='workView')workView=id;if(action==='shopView')shopView=id;if(action==='branch')branch=id;if(action==='shopFilter')shopFilter=id;if(action==='rankMode')rankMode=id;render();motion.enter();return;}
if(['settings','tasks','achievements','event','bonuses'].includes(action)){showModal(action);return;}if(action==='close'){closeModal();return;}
if(action==='collect'||action==='offlineClaim'){transact(()=>game.collect(s),'money');if(action==='offlineClaim'){s.offline=null;closeModal();}analytics.track('tutorial_complete',{step:s.tutorial});}
else if(action==='work')transact(()=>game.work(s),'money');
else if(action==='job')transact(()=>game.takeJob(s,id),'unlock',t('ui.newJob'));
else if(action==='item')transact(()=>game.buyItem(s,id),'purchase',t('ui.purchased'));
else if(action==='housing')transact(()=>game.buyHousing(s,Number(id)),'purchase',t('ui.purchased'),true);
else if(action==='train')transact(()=>game.train(s,id),'click',t('ui.training'));
else if(action==='quest')transact(()=>game.claimQuest(s,id),'achievement',t('ui.reward'));
else if(action==='achievement')transact(()=>game.claimAchievement(s,id),'achievement',t('ui.reward'));
else if(action==='gift')transact(()=>game.claimGift(s),'achievement',t('ui.reward'));
else if(action==='eventChoice'){transact(()=>resolveEvent(s,id),'purchase',t('ui.eventResolved'));if(s.event===null)closeModal();}
else if(action==='reset')showModal('resetConfirm');
else if(action==='resetConfirmed'){const settings=s.settings;s=game.freshState();s.settings=settings;closeModal();tab='life';persist();render();}
else if(action==='export'){game.advance(s,Date.now());persist();const blob=new Blob([saves.export(s)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='generation-z-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
else if(action==='import')document.getElementById('import-file').click();
else if(action==='importConfirmed'){s=pendingImport;pendingImport=null;const result=game.advance(s,Date.now(),true);game.registerOffline(s,result);setLanguage(s.settings.language);document.documentElement.lang=s.settings.language;sound.music(s.settings.music);closeModal();persist();render();toast(t('ui.imported'));if(s.offline)showModal('offline');}
});
document.addEventListener('change',async event=>{if(frozen||!s)return;const el=event.target;if(el.id==='language'){s.settings.language=el.value;setLanguage(el.value);document.documentElement.lang=el.value;document.title=t('ui.title')+' · Idle Life';persist();render();}else if(el.dataset.setting){s.settings[el.dataset.setting]=el.checked;if(el.dataset.setting==='music')sound.music(el.checked);if(el.dataset.setting==='motion'||el.dataset.setting==='effects'){motion.cancel();sceneAnimator.applySettings();}persist();}else if(el.id==='import-file'){const file=el.files[0];if(!file)return;try{if(file.size>1000000)throw Error('Too large');pendingImport=saves.import(await file.text());showModal('importConfirm');}catch{toast(t('ui.invalidSave'),5000);}el.value='';}});
window.addEventListener('pagehide',()=>{if(s&&!frozen){game.advance(s,Date.now(),true);persist();analytics.track('session_end');}});
window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});
document.addEventListener('visibilitychange',()=>{if(!s||frozen)return;sceneAnimator.applySettings();if(document.hidden){game.advance(s,Date.now());persist();}else{const old=s.training,result=game.advance(s,Date.now(),true);if(old&&!s.training)toast(t('ui.courseDone'));if(result.seconds>=60){game.registerOffline(s,result);if(s.offline)showModal('offline');}render();persist();}});

if('serviceWorker' in navigator&&(location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
